
from typing import TypedDict, Optional, Any

from src.triage_agent.schemas import VulnerabilityAssessment


class TriageState(TypedDict):
    # Original vulnerability submitted by the user
    finding: str

    # Historical reports retrieved from ChromaDB
    retrieved_reports: list[str]

    # Structured assessment generated by Qwen
    assessment: Optional[VulnerabilityAssessment]

    # Record of tools executed during analysis
    tool_calls: list[dict[str, Any]]

    # Errors encountered during processing
    errors: list[str]
    validation_errors: list[str]

    # Human approval status
    approved: Optional[bool]

    # Message describing the approval decision
    approval_message: Optional[str]

    # Mock disclosure report generated after approval
    mock_disclosure: Optional[str]

    # Database row ids, set when persistence is enabled
    finding_id: Optional[int]
    assessment_id: Optional[int]
